#!/usr/bin/env bash
set -euo pipefail
WORKSPACE="/home/kavia/workspace/code-generation/recipe-finding-app-98606-98493/AIImageRecognitionService"
cd "${WORKSPACE}"
[ -f package.json ] || { echo "package.json missing; run scaffold/install first" >&2; exit 2; }
mkdir -p src/__tests__
# simple test that doesn't rely on App file location
cat > src/__tests__/smoke.test.js <<'EOF'
import React from 'react'
import { render } from '@testing-library/react'
test('smoke renders a fragment', () => {
  const { container } = render(<div data-testid="ok">ok</div>)
  expect(container.querySelector('[data-testid="ok"]')).toBeTruthy()
})
EOF
# ensure deterministic deps if lockfile present
if [ -f package-lock.json ]; then
  npm ci --prefer-offline --no-audit --no-fund --silent || { echo "npm ci failed before tests" >&2; exit 3; }
fi
CI=true npm test -- --watchAll=false || { echo "tests failed" >&2; exit 4; }
